@startuml

class Researcher {
  + name : string
  + surname : string
  + researchGroup : ResearchGroup
}

class ResearchGroup {
  + name : string
  + department : Department
}

class Department {
  + name : string
  + university : University
}

class WorkPackage {
  + id : int
  + title : string
  + leader : ResearchGroup
}

class University {
  + name : string
}

Researcher "1" -- "0..*" WorkPackage : assignedTo
WorkPackage "1" -- "1" ResearchGroup : leads
Researcher "0..*" -- "0..*" ResearchGroup : serviceDelivers

@enduml

